-- Run after the existing release gates and audit migration, against disposable fixtures only.
reset role;
update public.team_memberships set status='active';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.create_shooting_challenge('30000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000001','Fair daily practice',current_date,current_date+7,'UTC');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'challenge'->>'daily_cap')::int=300,'New challenges use the 300-point ceiling');
select public.test_denied($q$select public.create_capped_shooting_challenge(gen_random_uuid(),'10000000-0000-0000-0000-000000000001','Too high',current_date,current_date+3,'UTC',301)$q$,'22023','Publication cannot exceed 300');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date,3000,0,gen_random_uuid());
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'players'->0->>'total')::int=300,'3000 actual shots earn 300 points');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'players'->0->>'raw_total')::int=3000,'Actual effort stays available to the family');
select public.test_assert(not (public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'players'->0->>'bonus_boss')::boolean,'Excess volume earns no bonus badge');
select public.test_assert(public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'review_entries'='[]'::jsonb,'Family cannot inspect private coach review notes');
select public.test_denied($q$select public.review_shooting_entry('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date,1,'Approved by parent')$q$,'42501','Families cannot approve their own review');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.test_assert(jsonb_array_length(public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'review_entries')=1,'High totals appear on the private coach list');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000004',200,300)$q$,'22023','Cap locks after first positive entry');
select public.configure_shooting_rules('30000000-0000-0000-0000-000000000004',300,300,1500);
select public.review_shooting_entry('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date,1,'Confirmed with family');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'review_entries'->0->>'reviewed')::boolean,'Coach can review the current entry version');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'players'->0->>'total')::int=300,'Coach review never buys extra points');
select public.test_denied($q$select public.review_shooting_entry('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date,0,'Stale review')$q$,'40001','Stale review is rejected');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date,2500,1,gen_random_uuid());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.test_assert(not (public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'review_entries'->0->>'reviewed')::boolean,'Changed entry requires a fresh review');
reset role;
update public.players set owner_user_id='00000000-0000-0000-0000-000000000003' where id='20000000-0000-0000-0000-000000000002';
update public.shooting_challenges set start_date=current_date-4 where id='30000000-0000-0000-0000-000000000004';
update public.shooting_challenge_players set enrolled_at=clock_timestamp()-interval '5 days' where challenge_id='30000000-0000-0000-0000-000000000004';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000002',current_date,4000,0,gen_random_uuid());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.test_assert((select (p->>'raw_total')::int=300 and (p->>'bonus_total')::int=0 from jsonb_array_elements(public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->'players') p where p->>'player_id'='20000000-0000-0000-0000-000000000002'),'Other families cannot inspect excess practice totals');
select public.test_denied($q$select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date-3,100,0,gen_random_uuid())$q$,'22023','Older family backdating goes through the coach');
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date-2,100,0,gen_random_uuid());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001',current_date-3,100,0,gen_random_uuid(),'Confirmed older practice');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000004')->>'corrected')::boolean,'Older coach corrections remain audited');
reset role;
